# Which secrets each fleet command needs - generated by
# scripts/settings-manifest, do not edit. The cti-agent wrapper reads it to
# give a hand run the same ImportCredential= grants its timer has.
# program SECRET...  (a program with none is not listed)
cti-agent ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET FALCON_CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD REPORT_REDACTION_SALT
cti-alert CLIENT_SECRET
cti-appreport CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD
cti-appscan CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD
cti-budget CLAUDE_CODE_OAUTH_TOKEN
cti-domains GODADDY_PAT POD_API_TOKEN
cti-falcon FALCON_CLIENT_SECRET
cti-jira CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD
cti-mailbox CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD
cti-mailer CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET NVD_API_KEY
cti-patchtuesday CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD
cti-podprobe POD_API_TOKEN
cti-supplier CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD
cti-triage ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN FALCON_CLIENT_SECRET
cti-vmscan CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD
enrich.py ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET FALCON_CLIENT_SECRET JIRA_API_TOKEN NVD_API_KEY QUALYS_PASSWORD REPORT_REDACTION_SALT
fleet-owners ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET FALCON_CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD REPORT_REDACTION_SALT
mailer.py ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET FALCON_CLIENT_SECRET JIRA_API_TOKEN NVD_API_KEY QUALYS_PASSWORD REPORT_REDACTION_SALT
model-lane.sh ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN
run-appowners CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET JIRA_API_TOKEN NVD_API_KEY QUALYS_PASSWORD
run-appscan CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET JIRA_API_TOKEN NVD_API_KEY QUALYS_PASSWORD
run-checkin ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET FALCON_CLIENT_SECRET GODADDY_PAT JIRA_API_TOKEN NVD_API_KEY POD_API_TOKEN QUALYS_PASSWORD REPORT_REDACTION_SALT
run-digest ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET FALCON_CLIENT_SECRET JIRA_API_TOKEN NVD_API_KEY QUALYS_PASSWORD REPORT_REDACTION_SALT
run-domains CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET GODADDY_PAT JIRA_API_TOKEN NVD_API_KEY POD_API_TOKEN QUALYS_PASSWORD
run-mailbox-cleanup ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET FALCON_CLIENT_SECRET JIRA_API_TOKEN QUALYS_PASSWORD REPORT_REDACTION_SALT
run-patchtuesday CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET JIRA_API_TOKEN NVD_API_KEY QUALYS_PASSWORD
run-supplier ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET JIRA_API_TOKEN NVD_API_KEY QUALYS_PASSWORD
run-vmscan CLAUDE_CODE_OAUTH_TOKEN CLIENT_SECRET JIRA_API_TOKEN NVD_API_KEY QUALYS_PASSWORD
